// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 targetBlock) public {
        vm.assume(caller != address(0));

        uint256 b = bound(targetBlock, 1, type(uint64).max);

        uint256 ts = 1;

        vm.deal(caller, 100 ether);

        vm.roll(b);
        vm.warp(ts + b);

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        if (block.number % 15 == 0) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance == 10 ether);
        }
    }
}
